-- Member-readable exits retain cursors/checksums, never message snapshots or file copies.
CREATE TABLE nook_exit_clock(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL);
INSERT INTO nook_exit_clock VALUES(1,0);
CREATE TABLE nook_exit_changes(conversation TEXT PRIMARY KEY,revision INTEGER NOT NULL);
INSERT INTO nook_exit_changes SELECT id,0 FROM nook_conversations;
CREATE TABLE nook_exit_jobs(
 id TEXT PRIMARY KEY,owner TEXT NOT NULL,scope TEXT NOT NULL CHECK(scope IN ('permitted','conversation')),
 created TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('running','cancelled','complete')),
 identity_revision INTEGER NOT NULL,cursor_json TEXT NOT NULL,pages INTEGER NOT NULL DEFAULT 0,
 records INTEGER NOT NULL DEFAULT 0,files INTEGER NOT NULL DEFAULT 0,bytes INTEGER NOT NULL DEFAULT 0,
 omissions INTEGER NOT NULL DEFAULT 0,counts_json TEXT NOT NULL DEFAULT '{}',revision INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX nook_exit_job_owner ON nook_exit_jobs(owner,created,id);
CREATE TABLE nook_exit_scopes(job TEXT NOT NULL REFERENCES nook_exit_jobs(id) ON DELETE CASCADE,conversation TEXT NOT NULL,source_revision INTEGER NOT NULL,PRIMARY KEY(job,conversation));
CREATE TABLE nook_exit_pages(job TEXT NOT NULL REFERENCES nook_exit_jobs(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL,cursor_json TEXT NOT NULL,sha256 TEXT NOT NULL,records INTEGER NOT NULL,PRIMARY KEY(job,ordinal));
-- Opaque structural participant IDs follow the existing content-free history policy.
-- Baselines assert membership at adoption, never an invented original join date.
CREATE TABLE nook_exit_membership(seq INTEGER PRIMARY KEY AUTOINCREMENT,conversation TEXT NOT NULL,user TEXT NOT NULL,action TEXT NOT NULL CHECK(action IN ('baseline','join','leave')),at TEXT NOT NULL);
CREATE INDEX nook_exit_membership_scope ON nook_exit_membership(conversation,seq);
INSERT INTO nook_exit_membership(conversation,user,action,at) SELECT conversation,user,'baseline',strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM nook_members;
CREATE TRIGGER nook_exit_membership_join AFTER INSERT ON nook_members BEGIN INSERT INTO nook_exit_membership(conversation,user,action,at) VALUES(NEW.conversation,NEW.user,'join',strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER nook_exit_membership_leave AFTER DELETE ON nook_members BEGIN INSERT INTO nook_exit_membership(conversation,user,action,at) VALUES(OLD.conversation,OLD.user,'leave',strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER nook_exit_membership_scope_deleted AFTER DELETE ON nook_conversations BEGIN DELETE FROM nook_exit_membership WHERE conversation=OLD.id; END;
CREATE TRIGGER nook_exit_erased_owner AFTER DELETE ON nook_actors BEGIN DELETE FROM nook_exit_jobs WHERE owner=OLD.id; END;
CREATE TRIGGER nook_exit_change_nook_members_insert AFTER INSERT ON nook_members BEGIN INSERT INTO nook_exit_changes(conversation,revision) SELECT NEW.conversation,1 WHERE NEW.conversation IS NOT NULL ON CONFLICT(conversation) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER nook_exit_change_nook_members_update AFTER UPDATE ON nook_members BEGIN INSERT INTO nook_exit_changes(conversation,revision) SELECT OLD.conversation,1 WHERE OLD.conversation IS NOT NULL ON CONFLICT(conversation) DO UPDATE SET revision=revision+1; INSERT INTO nook_exit_changes(conversation,revision) SELECT NEW.conversation,1 WHERE NEW.conversation IS NOT NULL ON CONFLICT(conversation) DO UPDATE SET revision=revision+1; END;
